const b = $json.body ?? {};
const valido = (v) => typeof v === 'string' && /^\d{4}-(0[1-9]|1[0-2])$/.test(v);
if ((b.desde != null && !valido(b.desde)) || (b.hasta != null && !valido(b.hasta))) throw new Error('Período inválido');
const actual = new Intl.DateTimeFormat('en-CA', {timeZone:'America/Mexico_City', year:'numeric', month:'2-digit'}).format(new Date()).slice(0,7);
const [y,m] = actual.split('-').map(Number);
const anterior = m === 1 ? (y-1)+'-12' : y+'-'+String(m-1).padStart(2,'0');
const a = b.desde ?? anterior;
const z = b.hasta ?? actual;
return [{json:{desde:a <= z ? a : z, hasta:a <= z ? z : a}}];

const texto = (v) => v == null || String(v).trim() === '' ? null : String(v).trim();
const dia = (v) => v ? new Date(v).toISOString().slice(0,10) : null;
return $input.all().filter(({json:r}) => Number.isSafeInteger(Number(r.Id)) && Number(r.Id)>0).map(({json:r})=>({json:{
mes:dia(r.Mes), id:Number(r.Id),
primera_devolucion:r.PrimeraDevolucion, ultima_devolucion:r.UltimaDevolucion,
estado:texto(r.Estado), repartidor:texto(r.Repartidor), tienda:texto(r.Tienda),
destino:texto(r.Destino), poligono:texto(r.Poligono),
fecha_programado:dia(r.FechaProgramado),
visitas:r.Visitas == null ? null : Number(r.Visitas), actualizado_en:new Date().toISOString()
}}));
